    <script>
        function openBetaMenu() {
            const overlay = document.getElementById('beta-overlay');
            const mainContent = document.getElementById('main-content');

            // Hide main content with animation
            mainContent.classList.add('hidden');

            // Show overlay after a brief delay
            setTimeout(() => {
                overlay.classList.add('active');
            }, 200);
        }

        function closeBetaMenu() {
            const overlay = document.getElementById('beta-overlay');
            const mainContent = document.getElementById('main-content');

            // Hide overlay
            overlay.classList.remove('active');

            // Show main content after overlay animation
            setTimeout(() => {
                mainContent.classList.remove('hidden');
            }, 300);
        }

        function showImageGenerator() {
            const mainContent = document.getElementById('main-content');
            closeBetaMenu();

            // Show the image generator content
            setTimeout(() => {
                mainContent.style.display = 'block';
                mainContent.classList.remove('hidden');
            }, 500);
        }

        function showTab(tabName) {
            // Hide all tabs
            document.querySelectorAll('.tab-content').forEach(tab => {
                tab.classList.remove('active');
            });
            document.querySelectorAll('.tab').forEach(tab => {
                tab.classList.remove('active');
            });

            // Show selected tab
            document.getElementById(tabName + '-tab').classList.add('active');
            event.target.classList.add('active');
        }

        function showLoading(message = 'Kép generálása folyamatban...') {
            document.getElementById('results').innerHTML = `
                <div class="loading">
                    <div class="spinner"></div>
                    ${message}
                </div>
            `;
        }

        function showError(message) {
            document.getElementById('results').innerHTML = `
                <div class="error-message">
                    <strong>Hiba:</strong> ${message}
                </div>
            `;
        }

        function showResult(data, endpoint) {
            const resultsDiv = document.getElementById('results');

            if (endpoint === 'generate_combined') {
                let html = '<div class="result-item"><h3>Generált képek mindkét modellel:</h3>';

                data.results.forEach(result => {
                    if (result.success) {
                        html += `
                            <div class="result-header">
                                <span class="model-name">${result.model}</span>
                                Letöltés
                            </div>
                            <img src="${result.image_url}" alt="Generált kép - ${result.model}" class="result-image">
                        `;
                    } else {
                        html += `
                            <div class="result-header">
                                <span class="model-name">${result.model}</span>
                            </div>
                            <div class="error-message">Hiba: ${result.error}</div>
                        `;
                    }
                });

                html += '</div>';
                resultsDiv.innerHTML = html;
            } else {
                resultsDiv.innerHTML = `
                    <div class="result-item">
                        <div class="result-header">
                            <span class="model-name">${data.model}</span>
                            Letöltés
                        </div>
                        <img src="${data.image_url}" alt="Generált kép" class="result-image">
                        <p><strong>Prompt:</strong> ${data.prompt}</p>
                    </div>
                `;
            }
        }

        async function generateImage(endpoint, formData) {
            showLoading();

            try {
                const response = await fetch(`/${endpoint}`, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                    },
                    body: JSON.stringify(formData)
                });

                const data = await response.json();

                if (data.success) {
                    showResult(data, endpoint);
                } else {
                    showError(data.error || 'Ismeretlen hiba történt');
                }
            } catch (error) {
                showError(`Hálózati hiba: ${error.message}`);
            }
        }

        document.getElementById('imagen-form').addEventListener('submit', async (e) => {
            e.preventDefault();

            const formData = {
                prompt: document.getElementById('imagen-prompt').value,
                aspect_ratio: document.getElementById('imagen-aspect-ratio').value,
                safety_filter_level: document.getElementById('imagen-safety').value,
                output_format: 'png'
            };

            await generateImage('generate_imagen', formData);
        });

        document.getElementById('flux-form').addEventListener('submit', async (e) => {
            e.preventDefault();

            const formData = {
                prompt: document.getElementById('flux-prompt').value,
                aspect_ratio: document.getElementById('flux-aspect-ratio').value,
                finetune_id: document.getElementById('flux-finetune-id').value,
                finetune_strength: parseFloat(document.getElementById('flux-finetune-strength').value),
                safety_tolerance: parseInt(document.getElementById('flux-safety').value)
            };

            const seed = document.getElementById('flux-seed').value;
            if (seed) {
                formData.seed = parseInt(seed);
            }

            await generateImage('generate_flux', formData);
        });

        document.getElementById('combined-form').addEventListener('submit', async (e) => {
            e.preventDefault();

            const formData = {
                prompt: document.getElementById('combined-prompt').value,
                aspect_ratio: document.getElementById('combined-aspect-ratio').value
            };

            showLoading('Képek generálása folyamatban mindkét modellel...');
            await generateImage('generate_combined', formData);
        });
    </script>
