## Modern Flask alkalmazás Google AI API-val

### app.py

```python
from flask import Flask, render_template, request, jsonify, send_file
import os
import requests
from io import BytesIO
import uuid
import base64
import json
import logging
from google.oauth2 import service_account
from google.auth.transport.requests import Request
import asyncio
import aiohttp
from functools import wraps
import time
from datetime import datetime, timedelta
import hashlib

# Logging konfigurálás
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

app = Flask(__name__)

class GoogleAIClient:
    def __init__(self):
        self.credentials = None
        self.project_id = None
        self.location = "us-central1"
        self.base_url = ""
        self._initialize_credentials()

    def _initialize_credentials(self):
        """Service Account credentials inicializálása Replit Secrets-ből"""
        try:
            # Service Account JSON betöltése Replit Secrets-ből
            service_account_json = os.environ.get('GOOGLE_SERVICE_ACCOUNT_JSON')
            if not service_account_json:
                raise ValueError("GOOGLE_SERVICE_ACCOUNT_JSON nem található a Secrets-ben")

            # JSON string parse-olása
            service_account_info = json.loads(service_account_json)

            # Credentials létrehozása
            self.credentials = service_account.Credentials.from_service_account_info(
                service_account_info,
                scopes=['']
            )

            self.project_id = service_account_info.get('project_id')
            if not self.project_id:
                raise ValueError("project_id nem található a Service Account JSON-ben")

            logger.info(f"Google AI Client inicializálva project_id: {self.project_id}")

        except Exception as e:
            logger.error(f"Hiba a credentials inicializálásakor: {str(e)}")
            raise

    def _get_access_token(self):
        """Friss access token beszerzése"""
        if not self.credentials.token or self.credentials.expired:
            self.credentials.refresh(Request())
        return self.credentials.token

    async def generate_image_async(self, prompt, **kwargs):
        """Aszinkron képgenerálás Google Imagen API-val"""
        try:
            access_token = self._get_access_token()

            endpoint = f"{self.base_url}/projects/{self.project_id}/locations/{self.location}/publishers/google/models/imagen-4-ultra:predict"

            headers = {
                'Authorization': f'Bearer {access_token}',
                'Content-Type': 'application/json'
            }

            # Request payload összeállítása
            payload = {
                "instances": [{
                    "prompt": prompt,
                    "aspectRatio": kwargs.get('aspect_ratio', '1:1'),
                    "safetyFilterLevel": kwargs.get('safety_filter_level', 'block_medium_and_above'),
                    "outputFormat": kwargs.get('output_format', 'png')
                }],
                "parameters": {
                    "sampleCount": 1
                }
            }

            async with aiohttp.ClientSession() as session:
                async with session.post(endpoint, headers=headers, json=payload) as response:
                    if response.status == 200:
                        result = await response.json()

                        # Base64 képadat kinyerése
                        if 'predictions' in result and len(result['predictions']) > 0:
                            image_data = result['predictions'][0].get('bytesBase64Encoded')
                            if image_data:
                                # Kép URL generálása (ideiglenes tárolás)
                                image_url = self._store_temp_image(image_data)
                                return {
                                    'success': True,
                                    'image_url': image_url,
                                    'model': 'Google Imagen 4 Ultra (Direct API)'
                                }

                        raise Exception("Nem sikerült képet generálni a válaszból")
                    else:
                        error_text = await response.text()
                        raise Exception(f"API hiba ({response.status}): {error_text}")

        except Exception as e:
            logger.error(f"Hiba a képgeneráláskor: {str(e)}")
            return {
                'success': False,
                'error': str(e)
            }

    def _store_temp_image(self, base64_data):
        """Ideiglenes képtárolás base64 adatból"""
        try:
            # Egyedi fájlnév generálása
            filename = f"temp_image_{uuid.uuid4().hex[:8]}.png"
            filepath = os.path.join('temp_images', filename)

            # Temp könyvtár létrehozása ha nem létezik
            os.makedirs('temp_images', exist_ok=True)

            # Base64 dekódolás és fájl mentése
            image_data = base64.b64decode(base64_data)
            with open(filepath, 'wb') as f:
                f.write(image_data)

            # URL visszaadása
            return f"/temp_image/{filename}"

        except Exception as e:
            logger.error(f"Hiba a kép tároláskor: {str(e)}")
            raise

# Rate limiting dekorátor
def rate_limit(max_calls=10, time_window=60):
    calls = {}

    def decorator(f):
        @wraps(f)
        def wrapper(*args, **kwargs):
            now = time.time()
            client_ip = request.remote_addr

            if client_ip not in calls:
                calls[client_ip] = []

            # Régi hívások törlése
            calls[client_ip] = [call_time for call_time in calls[client_ip] 
                              if now - call_time < time_window]

            if len(calls[client_ip]) >= max_calls:
                return jsonify({
                    'error': 'Túl sok kérés. Kérjük várjon egy percet.',
                    'retry_after': time_window
                }), 429

            calls[client_ip].append(now)
            return f(*args, **kwargs)

        return wrapper
    return decorator

# Cache egyszerű implementációja
class SimpleCache:
    def __init__(self, ttl=300):  # 5 perc TTL
        self.cache = {}
        self.ttl = ttl

    def get(self, key):
        if key in self.cache:
            data, timestamp = self.cache[key]
            if time.time() - timestamp < self.ttl:
                return data
            else:
                del self.cache[key]
        return None

    def set(self, key, value):
        self.cache[key] = (value, time.time())

# Globális objektumok
google_ai_client = GoogleAIClient()
image_cache = SimpleCache()

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/generate_imagen', methods=['POST'])
@rate_limit(max_calls=5, time_window=60)
async def generate_imagen():
    """Google Imagen 4 Ultra képgenerálás Direct API-val"""
    try:
        data = request.get_json()
        prompt = data.get('prompt', '').strip()

        if not prompt:
            return jsonify({'error': 'A szöveg prompt szükséges'}), 400

        # Cache kulcs generálása
        cache_key = hashlib.md5(
            f"{prompt}{data.get('aspect_ratio', '1:1')}{data.get('safety_filter_level', 'block_medium_and_above')}".encode()
        ).hexdigest()

        # Cache ellenőrzése
        cached_result = image_cache.get(cache_key)
        if cached_result:
            logger.info(f"Cache találat: {cache_key}")
            return jsonify(cached_result)

        # Képgenerálás
        result = await google_ai_client.generate_image_async(
            prompt=prompt,
            aspect_ratio=data.get('aspect_ratio', '1:1'),
            safety_filter_level=data.get('safety_filter_level', 'block_medium_and_above'),
            output_format=data.get('output_format', 'png')
        )

        if result['success']:
            result['prompt'] = prompt
            result['generated_at'] = datetime.now().isoformat()

            # Cache-elés
            image_cache.set(cache_key, result)

            logger.info(f"Sikeres képgenerálás: {prompt[:50]}...")
            return jsonify(result)
        else:
            logger.error(f"Képgenerálás hiba: {result['error']}")
            return jsonify(result), 500

    except Exception as e:
        logger.error(f"Váratlan hiba a generate_imagen-ban: {str(e)}")
        return jsonify({'error': f'Szerver hiba: {str(e)}'}), 500

@app.route('/temp_image/<filename>')
def serve_temp_image(filename):
    """Ideiglenes képek kiszolgálása"""
    try:
        filepath = os.path.join('temp_images', filename)
        if os.path.exists(filepath):
            return send_file(filepath, mimetype='image/png')
        else:
            return "Kép nem található", 404
    except Exception as e:
        logger.error(f"Hiba a kép kiszolgáláskor: {str(e)}")
        return "Hiba a kép betöltésekor", 500

@app.route('/download')
def download_image():
    """Kép letöltése"""
    image_url = request.args.get('url')
    if not image_url:
        return "Nincs kép URL megadva", 400

    try:
        if image_url.startswith('/temp_image/'):
            # Lokális temp kép
            filename = image_url.split('/')[-1]
            filepath = os.path.join('temp_images', filename)
            if os.path.exists(filepath):
                download_name = f"generated_image_{uuid.uuid4().hex[:8]}.png"
                return send_file(filepath, as_attachment=True, download_name=download_name)
        else:
            # Külső URL
            response = requests.get(image_url)
            response.raise_for_status()

            img_io = BytesIO(response.content)
            img_io.seek(0)

            filename = f"generated_image_{uuid.uuid4().hex[:8]}.png"
            return send_file(img_io, mimetype='image/png', as_attachment=True, download_name=filename)

    except Exception as e:
        logger.error(f"Hiba a kép letöltésekor: {str(e)}")
        return f"Hiba a kép letöltésekor: {str(e)}", 500

@app.route('/health')
def health_check():
    """Alkalmazás állapot ellenőrzése"""
    try:
        # Service Account ellenőrzése
        token = google_ai_client._get_access_token()
        return jsonify({
            'status': 'healthy',
            'timestamp': datetime.now().isoformat(),
            'google_auth': 'ok' if token else 'failed',
            'project_id': google_ai_client.project_id
        })
    except Exception as e:
        return jsonify({
            'status': 'unhealthy',
            'error': str(e),
            'timestamp': datetime.now().isoformat()
        }), 500

@app.route('/stats')
def get_stats():
    """Alkalmazás statisztikák"""
    return jsonify({
        'cache_size': len(image_cache.cache),
        'temp_images': len(os.listdir('temp_images')) if os.path.exists('temp_images') else 0,
        'uptime': datetime.now().isoformat()
    })

# Temp fájlok tisztítása induláskor
def cleanup_temp_files():
    """Régi temp fájlok törlése"""
    try:
        if os.path.exists('temp_images'):
            for filename in os.listdir('temp_images'):
                filepath = os.path.join('temp_images', filename)
                # 1 óránál régebbi fájlok törlése
                if os.path.getmtime(filepath) < time.time() - 3600:
                    os.remove(filepath)
                    logger.info(f"Régi temp fájl törölve: {filename}")
    except Exception as e:
        logger.error(f"Hiba a temp fájlok tisztításakor: {str(e)}")

if __name__ == '__main__':
    # Temp fájlok tisztítása induláskor
    cleanup_temp_files()

    # Környezeti változók
    debug_mode = os.environ.get('FLASK_DEBUG', 'False').lower() == 'true'
    port = int(os.environ.get('PORT', 5000))

    logger.info(f"Alkalmazás indítása - Debug: {debug_mode}, Port: {port}")

    app.run(host='0.0.0.0', port=port, debug=debug_mode)
